bool RequestManager::IsNeedStopUsingPermission(const pid_t pid)
{
    std::unique_lock<ffrt::mutex> uniquelock(workingPidsCountMutex_);
    if (workingPidsCountMap_.count(pid) <= 0) {
        return false;
